def maxAlternatingParityDescent(triangle):
    down = triangle[-1][:]
    for i in range(len(triangle) - 2, -1, -1):
        child = triangle[i + 1]
        new = []
        for j in range(i + 1):
            v = triangle[i][j]
            best = -1
            for k in (j, j + 1):
                if (child[k] - v) % 2 == 1 and down[k] > best:
                    best = down[k]
            new.append(v + best if best >= 0 else -1)
        down = new
    return down[0]
